  EXTERNAL_IDENTITY_V3_CHECKPOINT_READER_BRIDGE_CORE_PATHS.length > 0
  && (() => {
    try {
      git(process.cwd(), [
        "cat-file", "-e",
        EXTERNAL_IDENTITY_V3_CHECKPOINT_READER_BRIDGE_PARENT_SHA + "^{commit}"
      ]);
      return true;
    } catch {
      return false;
    }
  })();
